//! Shared by `portable_art_copy.rs`: ID3v2.4, RIFF/AIFF and multi-picture FLAC writers and an independent ID3
//! picture parser (no TagLib), so the bridge's output is checked by code that does not share its assumptions.
//! Only generated bytes are used.
#![allow(dead_code)]

use std::ops::Range;

/// An ID3v2 tag size is a 28-bit synchsafe integer (frames plus padding, not the 10-byte header).
pub const ID3_LIMIT: usize = 0x0fff_ffff;
/// TagLib 1.11.1 pads a tag that outgrew its old size with this many zero bytes.
pub const ID3_PADDING: usize = 1024;
/// The largest FLAC metadata block.
pub const FLAC_BLOCK_LIMIT: usize = 0xff_ffff;

pub fn synchsafe(value: usize) -> [u8; 4] {
    assert!(value <= ID3_LIMIT, "{value} does not fit a synchsafe integer");
    [(value >> 21) as u8 & 0x7f, (value >> 14) as u8 & 0x7f, (value >> 7) as u8 & 0x7f, value as u8 & 0x7f]
}
pub fn unsynchsafe(bytes: &[u8]) -> usize { bytes[..4].iter().fold(0, |value, byte| (value << 7) | usize::from(byte & 0x7f)) }

pub fn frame(id: &[u8; 4], body: &[u8]) -> Vec<u8> {
    let mut out = id.to_vec();
    out.extend_from_slice(&synchsafe(body.len()));
    out.extend_from_slice(&[0, 0]);
    out.extend_from_slice(body);
    out
}
/// A UTF-8 text frame.
pub fn text_frame(id: &[u8; 4], text: &str) -> Vec<u8> {
    let mut body = vec![3];
    body.extend_from_slice(text.as_bytes());
    body.push(0);
    frame(id, &body)
}
/// An APIC frame. `utf16` writes the description as UTF-16 with a byte order mark (twice as wide), otherwise Latin-1
/// (ASCII only here).
pub fn apic_frame(mime: &str, picture_type: u8, description: &str, data: &[u8], utf16: bool) -> Vec<u8> {
    let mut body = vec![u8::from(utf16)];
    body.extend_from_slice(mime.as_bytes());
    body.push(0);
    body.push(picture_type);
    if utf16 {
        body.extend_from_slice(&[0xff, 0xfe]);
        for unit in description.encode_utf16() { body.extend_from_slice(&unit.to_le_bytes()); }
        body.extend_from_slice(&[0, 0]);
    } else {
        assert!(description.is_ascii());
        body.extend_from_slice(description.as_bytes());
        body.push(0);
    }
    body.extend_from_slice(data);
    frame(b"APIC", &body)
}
/// The bytes an APIC frame costs on top of its picture.
pub fn apic_overhead(mime: &str, description: &str, utf16: bool) -> usize { apic_frame(mime, 3, description, &[], utf16).len() }

pub fn id3v24_tag(frames: &[Vec<u8>]) -> Vec<u8> {
    let size: usize = frames.iter().map(Vec::len).sum();
    let mut tag = vec![b'I', b'D', b'3', 4, 0, 0];
    tag.extend_from_slice(&synchsafe(size));
    for frame in frames { tag.extend_from_slice(frame); }
    tag
}

/// The size field of the ID3v2 header at `offset`, or `None` without one.
pub fn tag_field(file: &[u8], offset: usize) -> Option<usize> {
    (file.len() >= offset + 10 && &file[offset..offset + 3] == b"ID3").then(|| unsynchsafe(&file[offset + 6..offset + 10]))
}

/// A picture of an ID3 tag as the independent parser sees it; `data` indexes the file it came from.
#[derive(Debug, Clone)]
pub struct Apic { pub picture_type: u8, pub mime: String, pub description: String, pub data: Range<usize> }

/// Every APIC frame of the ID3v2.3/2.4 tag at `offset`, in order.
pub fn parse_apics(file: &[u8], offset: usize) -> Vec<Apic> {
    let field = tag_field(file, offset).expect("an ID3v2 header");
    let version = file[offset + 3];
    let end = offset + 10 + field;
    assert!(end <= file.len(), "the tag size field points past the file");
    let mut position = offset + 10;
    let mut out = Vec::new();
    while position + 10 <= end && file[position] != 0 {
        let id = &file[position..position + 4];
        let size_bytes = &file[position + 4..position + 8];
        let size = if version == 4 { unsynchsafe(size_bytes) } else { u32::from_be_bytes(size_bytes.try_into().unwrap()) as usize };
        let body = position + 10..position + 10 + size;
        assert!(body.end <= end, "a frame runs past the tag");
        if id == b"APIC" {
            let bytes = &file[body.clone()];
            let encoding = bytes[0];
            let mime_end = bytes[1..].iter().position(|&b| b == 0).expect("mime terminator") + 1;
            let mime = String::from_utf8(bytes[1..mime_end].to_vec()).unwrap();
            let picture_type = bytes[mime_end + 1];
            let text = mime_end + 2;
            let (description, after) = match encoding {
                0 | 3 => {
                    let n = bytes[text..].iter().position(|&b| b == 0).expect("description terminator");
                    let raw = &bytes[text..text + n];
                    (if encoding == 0 { raw.iter().map(|&b| b as char).collect() } else { String::from_utf8(raw.to_vec()).unwrap() }, text + n + 1)
                }
                1 | 2 => {
                    let mut units = Vec::new();
                    let mut cursor = text;
                    let mut big = encoding == 2;
                    if encoding == 1 {
                        big = bytes[cursor..cursor + 2] == [0xfe, 0xff];
                        cursor += 2;
                    }
                    while bytes[cursor..cursor + 2] != [0, 0] {
                        let pair = [bytes[cursor], bytes[cursor + 1]];
                        units.push(if big { u16::from_be_bytes(pair) } else { u16::from_le_bytes(pair) });
                        cursor += 2;
                    }
                    (String::from_utf16(&units).unwrap(), cursor + 2)
                }
                other => panic!("unknown APIC text encoding {other}"),
            };
            out.push(Apic { picture_type, mime, description, data: body.start + after..body.end });
        }
        position = body.end;
    }
    out
}

/// `[(chunk id, payload range)]` of a RIFF (little-endian) or FORM (big-endian) container, in file order.
pub fn riff_chunks(file: &[u8], big_endian: bool) -> Vec<([u8; 4], Range<usize>)> {
    let read = |at: usize| -> usize {
        let raw: [u8; 4] = file[at..at + 4].try_into().unwrap();
        (if big_endian { u32::from_be_bytes(raw) } else { u32::from_le_bytes(raw) }) as usize
    };
    let end = (read(4) + 8).min(file.len());
    let mut out = Vec::new();
    let mut position = 12;
    while position + 8 <= end {
        let id: [u8; 4] = file[position..position + 4].try_into().unwrap();
        let size = read(position + 4);
        let body = position + 8..(position + 8 + size).min(file.len());
        position = body.end + (size & 1);
        out.push((id, body));
    }
    out
}
/// The payload offset of the `ID3 ` (or `id3 `) chunk.
pub fn riff_id3_offset(file: &[u8], big_endian: bool) -> Option<usize> {
    riff_chunks(file, big_endian).into_iter().find(|(id, _)| id.eq_ignore_ascii_case(b"ID3 ")).map(|(_, body)| body.start)
}
/// The sample data: `data` of a WAV, `SSND` of an AIFF.
pub fn riff_audio(file: &[u8], big_endian: bool) -> &[u8] {
    let wanted: &[u8; 4] = if big_endian { b"SSND" } else { b"data" };
    let (_, body) = riff_chunks(file, big_endian).into_iter().find(|(id, _)| id == wanted).expect("an audio chunk");
    &file[body]
}

fn chunk(id: &[u8; 4], body: &[u8], big_endian: bool) -> Vec<u8> {
    let size = body.len() as u32;
    let mut out = id.to_vec();
    out.extend_from_slice(&if big_endian { size.to_be_bytes() } else { size.to_le_bytes() });
    out.extend_from_slice(body);
    if body.len() & 1 == 1 { out.push(0); }
    out
}
fn container(form: &[u8; 4], kind: &[u8; 4], chunks: &[Vec<u8>], big_endian: bool) -> Vec<u8> {
    let body: Vec<u8> = chunks.concat();
    let size = (4 + body.len()) as u32;
    let mut out = form.to_vec();
    out.extend_from_slice(&if big_endian { size.to_be_bytes() } else { size.to_le_bytes() });
    out.extend_from_slice(kind);
    out.extend_from_slice(&body);
    out
}
/// A 16-bit stereo 44.1 kHz WAV of 100 sample frames, optionally with an `ID3 ` chunk after the data.
pub fn wav(tag: Option<&[u8]>) -> Vec<u8> {
    let mut fmt = vec![1, 0, 2, 0];
    fmt.extend_from_slice(&44_100u32.to_le_bytes());
    fmt.extend_from_slice(&(44_100u32 * 4).to_le_bytes());
    fmt.extend_from_slice(&[4, 0, 16, 0]);
    let samples: Vec<u8> = (0..400u32).map(|n| (n % 251) as u8).collect();
    let mut chunks = vec![chunk(b"fmt ", &fmt, false), chunk(b"data", &samples, false)];
    if let Some(tag) = tag { chunks.push(chunk(b"ID3 ", tag, false)); }
    container(b"RIFF", b"WAVE", &chunks, false)
}
/// A 16-bit stereo 44.1 kHz AIFF of 100 sample frames, optionally with an `ID3 ` chunk after the sound data.
pub fn aiff(tag: Option<&[u8]>) -> Vec<u8> {
    let mut comm = 2u16.to_be_bytes().to_vec();
    comm.extend_from_slice(&100u32.to_be_bytes());
    comm.extend_from_slice(&16u16.to_be_bytes());
    comm.extend_from_slice(&[0x40, 0x0e, 0xac, 0x44, 0, 0, 0, 0, 0, 0]);
    let mut ssnd = vec![0u8; 8];
    ssnd.extend((0..400u32).map(|n| (n % 241) as u8));
    let mut chunks = vec![chunk(b"COMM", &comm, true), chunk(b"SSND", &ssnd, true)];
    if let Some(tag) = tag { chunks.push(chunk(b"ID3 ", tag, true)); }
    container(b"FORM", b"AIFF", &chunks, true)
}

/// One picture block of a generated FLAC.
pub struct FlacPicture<'a> { pub kind: u32, pub mime: &'a str, pub description: &'a str, pub geometry: [u32; 4], pub data: &'a [u8] }

/// STREAMINFO, a Vorbis comment (title, BPM and key, so the tags copy), the picture blocks and junk where the audio
/// would be: all TagLib needs to read the tags.
pub fn flac_with_pictures(pictures: &[FlacPicture]) -> Vec<u8> {
    fn block(kind: u8, last: bool, data: &[u8]) -> Vec<u8> {
        assert!(data.len() <= FLAC_BLOCK_LIMIT, "FLAC block too large");
        let n = data.len();
        let mut v = vec![kind | if last { 128 } else { 0 }, (n >> 16) as u8, (n >> 8) as u8, n as u8];
        v.extend_from_slice(data);
        v
    }
    let mut xiph = 7u32.to_le_bytes().to_vec();
    xiph.extend_from_slice(b"fixture");
    let fields = [&b"TITLE=Art source"[..], b"ARTIST=Art artist", b"BPM=128", b"INITIALKEY=Am"];
    xiph.extend_from_slice(&(fields.len() as u32).to_le_bytes());
    for field in fields {
        xiph.extend_from_slice(&(field.len() as u32).to_le_bytes());
        xiph.extend_from_slice(field);
    }
    let mut data = b"fLaC".to_vec();
    data.extend(block(0, false, &[0; 34]));
    data.extend(block(4, pictures.is_empty(), &xiph));
    for (index, picture) in pictures.iter().enumerate() {
        let mut body = picture.kind.to_be_bytes().to_vec();
        body.extend_from_slice(&(picture.mime.len() as u32).to_be_bytes());
        body.extend_from_slice(picture.mime.as_bytes());
        body.extend_from_slice(&(picture.description.len() as u32).to_be_bytes());
        body.extend_from_slice(picture.description.as_bytes());
        for value in picture.geometry { body.extend_from_slice(&value.to_be_bytes()); }
        body.extend_from_slice(&(picture.data.len() as u32).to_be_bytes());
        body.extend_from_slice(picture.data);
        data.extend(block(6, index + 1 == pictures.len(), &body));
    }
    data.extend_from_slice(&[0x55; 256]);
    data
}

/// `png` followed by zero bytes up to `total`: a structurally complete PNG with trailing data, which the bridge accepts.
pub fn padded(png: &[u8], total: usize) -> Vec<u8> {
    assert!(total >= png.len());
    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(png);
    out.resize(total, 0);
    out
}
